import React, { useState, useEffect } from "react";
import axios from "axios";
import Map from "./components/Map";
import PlantDetails from "./components/PlantDetails";
import AdminPanel from "./components/AdminPanel";
import "./App.css";

const API_URL = "http://localhost:4000"; // Замени на адрес своего backend

function App() {
    const [plants, setPlants] = useState([]);
    const [selectedPlant, setSelectedPlant] = useState(null);
    const [isAdmin, setIsAdmin] = useState(false);
    const [addMode, setAddMode] = useState(false);
    const [pendingCoords, setPendingCoords] = useState(null);

    /*useEffect(() => {
        axios.get(`${API_URL}/plants`).then(res => setPlants(res.data));
        console.log("daw");
    }, []);*/

    const handleMarkerClick = (plant) => setSelectedPlant(plant);
    const handleCloseDetails = () => setSelectedPlant(null);

    const handleAdd = (plant) => {
        axios.post(`${API_URL}/plants`, plant)
            .then(res => setPlants(plants => [...plants, res.data]));
    };

    const handleEdit = (updatedPlant) => {
        axios.put(`${API_URL}/plants/${updatedPlant.id}`, updatedPlant)
            .then(() => setPlants(plants => plants.map(
                p => p.id === updatedPlant.id ? updatedPlant : p
            )));
    };

    const handleDelete = (id) => {
        axios.delete(`${API_URL}/plants/${id}`)
            .then(() => setPlants(plants => plants.filter(p => p.id !== id)));
    };

    return (
        <div className="App">
            <header>
                <h1>Карта заводов</h1>
                <button onClick={() => setIsAdmin((v) => !v)}>
                    {isAdmin ? "Выйти из админ-панели" : "Войти в админ-панель"}
                </button>
            </header>
            {isAdmin ? (
                <AdminPanel
                    plants={plants}
                    onAdd={handleAdd}
                    onEdit={handleEdit}
                    onDelete={handleDelete}
                    addMode={addMode}
                    setAddMode={setAddMode}
                    pendingCoords={pendingCoords}
                    setPendingCoords={setPendingCoords}
                />
            ) : (
                <>
                    <Map plants={plants} onMarkerClick={handleMarkerClick} />
                    {selectedPlant && (
                        <PlantDetails plant={selectedPlant} onClose={handleCloseDetails} />
                    )}
                </>
            )}
        </div>
    );
}

export default App;
